"""Measured free root + articulation and the exact contracted source/target anchors."""
import hashlib,json,shutil
from pathlib import Path
import xml.etree.ElementTree as E
import numpy as np
from scipy.spatial.transform import Rotation
from .free_articulated import FreeCase,FreePlan
from .execution import ExecutionTrace
from .articulated_view import boxes
TITLES={'free_box_lid':'자유 박스 · 본체 grip/support + 뚜껑 열기','free_folding_object':'자유 접이식 패널 · 본체 지지 + 날개 펼치기','free_portable_drawer':'자유 수납함 · 본체 지지 + 서랍 당기기'}

def export_free(plan,trace,report,flags,web_directory,frames=541):
 web=Path(web_directory);(web/'data').mkdir(parents=True,exist_ok=True);case=plan.case;d=case.data;id=d['id'];idx=np.unique(np.linspace(0,len(trace.time)-1,frames).round().astype(int));theta=np.array(trace.metadata['articulated_state']['q'])[:,0];q=np.c_[trace.q[idx],trace.object_pose[idx,0],theta[idx]];positions=[[] for _ in idx];names=[];edges=[];instances=[];off=0
 for i,r in enumerate([*case.full,case.object]):
  floating=i==3;name='object' if floating else f'arm{i}';tool=None if floating else d['arms'][i]['kind'];modelid='free_'+(id if floating else tool.lower()+'_panda');directory=web/'models'/modelid;directory.mkdir(parents=True,exist_ok=True);shutil.copyfile(r.path,directory/'robot.urdf');lic='LICENSE.authored' if floating else 'LICENSE.panda';shutil.copyfile(case.path.parent/lic,directory/lic);shutil.copyfile(case.path.parent/'LICENSE.authored',directory/'LICENSE.authored');meta=dict(packages={},source='Authored free articulated body with internal joint',license='MIT') if floating else json.loads((case.path.parent/'franka_panda_provenance.json').read_text());meta.update(id=modelid,urdf='robot.urdf',license_file=lic,urdf_sha256=hashlib.sha256(r.path.read_bytes()).hexdigest());(directory/'model.json').write_text(json.dumps(meta,indent=2)+'\n');indices=list(range(off,off+r.nq));off+=r.nq;spec=dict(id=name,role='free_articulated_object' if floating else 'contact_arm',manifest=f'./models/{modelid}/model.json',joint_names=r.joint_names,dof=r.n,floating_base=floating,q_indices=indices)
  if not floating:spec['base_pose']=dict(position=r.base_pose[:3,3].tolist(),quaternion_xyzw=Rotation.from_matrix(r.base_pose[:3,:3]).as_quat().tolist())
  instances.append(spec);links=list(r.tree.links);start=len(names);names += [name+'_'+n for n in links];edges += [[start+links.index(j.parent),start+links.index(j.child)] for j in r.tree.joints]
  for row,frame in zip(positions,range(len(idx))):row += [r.fk(q[frame,indices],link)[:3,3].tolist() for link in links]
 tree=E.parse(case.object.path);torque=np.r_[trace.torque,trace.torque[-1:]][idx];limits=np.concatenate([r.effort for r in case.full]);events=[]
 for pulse in trace.metadata.get('external_disturbances',[]):events += [dict(id='외력 시작',time=pulse['start']),dict(id='외력 최대 · 화살표',time=pulse['start']+pulse['duration']/2),dict(id='외력 종료',time=pulse['start']+pulse['duration'])]
 env=[dict(type='box',size=[.3,.3,r.base_pose[2,3]],position=[*r.base_pose[:2,3],r.base_pose[2,3]/2],quaternion_xyzw=[0,0,0,1],color='#687888') for r in case.full if r.base_pose[2,3]>0]
 data=dict(id=id,title=TITLES[id],scenario=id,free_articulated_object=True,articulated_object=True,multi_arm=True,contact_contraction=case.contraction,external_disturbances=trace.metadata.get('external_disturbances',[]),engine='mujoco_contact_recording',dof=sum(r.n for r in case.full),nq=q.shape[1],nv=sum(r.nv for r in case.full)+case.object.nv,floating_base=False,frame='link-aware source -> 3-arm realization -> free articulated dynamics',joint_names=trace.metadata['joint_names'],instances=instances,objects=[dict(id=link,index=names.index('object_'+link),poses=trace.object_pose[idx,i].tolist(),boxes=boxes(tree.find(f"link[@name='{link}']"))) for i,link in enumerate(['base','moving'])],times=trace.time[idx].round(6).tolist(),q=q.round(9).tolist(),positions=positions,link_names=names,edges=edges,torques=torque.tolist(),torque_ratio=np.max(abs(torque)/limits,axis=1).tolist(),errors=[None]*len(idx),chart_values=(theta[idx]*1000 if id=='free_portable_drawer' else np.rad2deg(theta[idx])).tolist(),chart_label='MEASURED INTERNAL JOINT · FREE BASE',chart_unit='mm' if id=='free_portable_drawer' else 'deg',keyframes=[dict(id=n,time=t) for n,t in [('grip_and_support',0),('lift_and_reorient',d['lift_end']),('begin_internal_motion',d['motion_start']),('mid_internal_motion',(d['motion_start']+d['motion_end'])/2),('target',d['motion_end']),('hold',d['duration'])]],events=events,tool_states={s['id']+' / '+s['group_id']:flags[idx,i].tolist() for i,s in enumerate(d['arms'])},environment=env,summary=dict(duration=float(trace.time[-1]),physics_dt=trace.metadata['timestep'],primal_residual=plan.residual,full_geometry_checked=False),report=report,description='Three Panda arms realize link-aware contracted contacts: base grasp, base support and internal-link manipulation. The complete articulated object has an unactuated free root and passive internal hinge/slider. No world hinge, object actuator or pose forcing. Dense source samples and functional group labels are synthetic supplied inputs; geometric contraction and target coupled realization are executed. Reference paths and assignment supplied; no learned inference or hardware calibration.')
 (web/f'data/{id}.json').write_text(json.dumps(data,separators=(',',':'),allow_nan=False));(web/f'data/{id}-preset.json').write_text(json.dumps(d,indent=2)+'\n');p=web/'data/index.json';catalog=json.loads(p.read_text()) if p.exists() else {'models':[]};catalog['models']=[{k:data[k] for k in ['id','title','engine','dof','floating_base']}]+[m for m in catalog['models'] if m['id']!=id];p.write_text(json.dumps(catalog,indent=2)+'\n');return data

def export_saved(id,web_directory='web',output=None):
 root=Path(output or 'outputs/'+id);c=FreeCase.load(id,root/'case.json');a=np.load(root/'plan.npz');r=json.loads((root/'report.json').read_text());p=FreePlan(c,a['time'],a['q'],a['v'],a['a'],a['wrenches'],a['torque'],r['primal_residual']);return export_free(p,ExecutionTrace.load(root/'execution.npz'),r,np.load(root/'metrics.npz')['flags'],web_directory)
